 "From game files and captured profiles to the catalogs, research and tools on ToF Hub. What we extract, what we calculate and what we maintain by hand.": "从游戏文件与抓取的档案，到 ToF Hub 上的目录、研究与工具。我们提取什么、计算什么、手动维护什么。",
