 "Calculations": "计算",
 "Scaling, derived stats, gear scores and simulations computed from supported inputs, with their own assumptions and limits.": "由受支持的输入计算得出的成长、衍生属性、装备评分与模拟，各有其假设与局限。",
 "Captures and imports": "抓取与导入",
 "Observed profiles, equipment, counters and order history. Coverage depends on what the game sends during collection.": "观察到的档案、装备、计数器与订单历史。覆盖范围取决于游戏在采集期间发送的内容。",
 "Editorial content": "编辑内容",
 "Readable names, explanations, artwork selections, team presets and some schedules, maintained separately from extracted game facts.": "易读的名称、说明、原画选择、队伍预设与部分日程，与提取的游戏事实分开维护。",
 "How each section uses the data": "各栏目如何使用数据",
 "Shared references feed several pages. Each feature selects the relevant records and adds its own presentation or calculations.": "共享的参考数据支撑多个页面。每个功能挑选相关记录，并加入自己的展示或计算。",
