 "Team and raid compositions": "队伍与团队副本阵容",
 "From an installed game to an update": "从已安装的游戏到一次更新",
 "The portable exporter runs the processing pipeline near the installed client. The website consumes its finished datasets and media.": "便携导出器在已安装客户端旁运行处理流程。网站使用其生成的数据集与媒体。",
 "Identify the client": "识别客户端",
 "Read installation and launcher metadata to record the exported version and branch.": "读取安装与启动器元数据，记录导出的版本与分支。",
 "Extract selected resources": "提取所选资源",
 "UnrealExporter reads configured paths from the game archives: tables, localization and the textures needed by the site.": "UnrealExporter 从游戏档案中读取已配置的路径：数据表、本地化，以及网站所需的贴图。",
 "Process and connect": "处理与关联",
 "Processors resolve identifiers and join tables to translations and media. Separate curated inputs add labels, notes and preserved resources.": "处理器解析标识，并将数据表与翻译和媒体关联。另行整理的输入补充标签、备注与保留的资源。",
 "Generate the site data": "生成网站数据",
 "Validate and package": "验证与打包",
 "Apply and publish": "应用与发布",
 "The update is applied to the site’s generated public files and checked before deployment. Exporting a client does not itself publish the website.": "更新会应用到网站生成的公开文件，并在部署前检查。导出客户端本身并不会发布网站。",
 "ToF Hub Live Capture": "ToF Hub 实时抓取",
 "Start before logging in": "在登录前启动",
 "Choose a task and follow the readiness checks. The app uses the WinDivert driver to observe network traffic and asks for Windows administrator rights.": "选择任务并按就绪检查操作。应用使用 WinDivert 驱动观察网络流量，并请求 Windows 管理员权限。",
 "Follow the in-game prompts": "按游戏内提示操作",
 "Save and import": "保存并导入",
 "Import files": "导入文件",
 "Checks and limits": "检查与局限",
 "Keep the source attached": "保留来源信息",
 "Record the source branch, export or capture time and known provenance. A test client can contain unreleased or unused records.": "记录来源分支、导出或抓取时间以及已知出处。测试客户端可能包含未上线或未使用的记录。",
 "Check relationships and calculations": "检查关联与计算",
 "Show uncertainty": "呈现不确定性",
 "Separate edits from observations": "区分编辑与观察",
 "A few file terms": "几个文件术语",
 "Unreal Engine archives and individual assets. Tables, configuration and textures are exported into readable formats.": "Unreal Engine 档案与单个资源。数据表、配置与贴图会被导出为可读格式。",
 "Localization supplies game text. JSON is the exported or generated representation used by the processors and website.": "本地化提供游戏文本。JSON 是处理器与网站使用的导出或生成格式。",
 "Extracted textures are converted for display. WebP serves the site; PNG is retained for supported original-image downloads.": "提取的贴图会转换后用于显示。网站使用 WebP；PNG 保留给受支持的原图下载。",
