 "Site": "网站",
 "Updated the dataset to 6.4.10, added the main hub and version history, and corrected MMO data processing.": "数据集更新至 6.4.10，新增主页与版本历史，并修正 MMO 数据处理。",
 "Added the main hub with Info, Tools and Datamine shortcuts. Version branches are grouped separately; history and patcher instructions open in dialogs.": "新增主页，含资料库、工具与数据挖掘快捷入口。版本分支分组显示；历史与补丁器说明在对话框中打开。",
 "Feature": "功能",
