 "Complete visual overhaul of Origin of War: progressive image loading, WebP asset optimization, responsive season cards, and deep-link affix breakdown.": "全面重制起源之战的视觉：渐进式图片加载、WebP 资源优化、响应式赛季卡片与可深链的词缀明细。",
 "Updated Datamine data for version 6.3.0.": "已将数据挖掘数据更新至 6.3.0 版本。",
 "Updated Season 23 data, enemy waves, and boss values.": "更新第 23 赛季数据、敌人波次与首领数值。",
