 "Structured game database covering Simulacra, weapons, matrices, relics, cosmetics, and food.": "涵盖拟态、武器、意志、源器、外观与食物的结构化游戏数据库。",
 "Tool": "工具",
 "by Kritik": "作者：Kritik",
