 "Wiki": "维基",
 "Community-maintained English wiki covering characters, weapons, systems, story and other Tower of Fantasy information.": "由社区维护的英文维基，涵盖角色、武器、系统、剧情及其他 Tower of Fantasy 信息。",
 "Dedicated interactive map resource with exploration markers, chests, puzzles, and collectible locations.": "专用的互动地图资源，含探索标记、宝箱、谜题与收集品位置。",
