 "Why weapon and matrix damage multipliers are separate": "为什么武器与意志伤害倍率是分开计算的",
 "Q: largest weighted maximum roll after the Titan multiplier, across the generated stat catalog.": "Q：泰坦倍率之后、生成的属性目录中加权最大词条的最大值。",
 "Q: largest weighted maximum roll after the Titan multiplier among the stats this role rates.": "Q：泰坦倍率之后，该定位所评分属性中加权最大词条的最大值。",
 "Titan-added stats: why equal rolls can give different HP": "泰坦追加属性：为什么相同词条会得到不同的生命值",
 "Equivalent rolls = (primary after Titan − primary initial value) / primary maximum roll": "等效词条数 =（泰坦后主属性 − 主属性初始值）/ 主属性最大词条",
 "Added stat = its initial value + observed share × equivalent rolls × its maximum roll": "追加属性 = 其初始值 + 观测占比 × 等效词条数 × 其最大词条",
 "enemy-level denominator": "敌人等级分母",
 "Both Crit weights are zero when c ≥ 1.": "当 c ≥ 1 时，两项暴击权重均为零。",
 "Equipped gear": "已装备的装备",
 "Build maximum": "配装最大值",
 "Build roll quality": "配装词条质量",
 "Equip at least one item and provide valid rating inputs for every equipped slot. Empty slots add no points; their ceilings remain part of the build maximum.": "请装备至少一件装备，并为每个已装备栏位提供有效的评分输入。空栏位不计分，但其上限仍计入配装最大值。",
 "Total of the equipped items’ GRV against the total of their slot ceilings, using one reference profile for everyone.": "已装备装备的 GRV 总和与其栏位上限总和之比，所有人使用同一参考档案。",
 "Total of the equipped items’ PRV against the total of their slot ceilings, using your current panel stats.": "已装备装备的 PRV 总和与其栏位上限总和之比，使用你当前的面板属性。",
 "Sum of the slot scores. Open the RV of an item for its own breakdown.": "各栏位分数之和。打开某件装备的 RV 可查看其单独明细。",
 "Share of the build maximum. It is not a damage bonus or a ranking among players.": "占配装最大值的比例。它不是伤害加成，也不是玩家之间的排名。",
 "Each item is rated after removing only that item, so the total is not the effect of removing or adding the whole set at once.": "每件装备都是在仅移除该装备后进行评分的，因此总和并不等于整套装备同时移除或添加的效果。",
