 "Enter base ATK, ATK%, DMG%, Crit and a supported enemy level. Totals must include this equipped item and remain valid after removal.": "请输入基础攻击、攻击%、伤害%、暴击以及受支持的敌人等级。合计值须包含此已装备装备，且移除后仍然有效。",
