 "Tied strongest stats: conservative estimate.": "并列最强属性：保守估计。",
 "One reference profile for everyone. Compare tank gear as it is now by the effective HP it adds against the selected element, independently of account stats.": "所有人使用同一参考档案。按所选元素，以该装备当前提供的有效生命值衡量坦克装备，与账号属性无关。",
 "One reference profile for everyone. Compare healer gear as it is now by the ATK it adds, independently of account stats.": "所有人使用同一参考档案。按该装备当前提供的攻击衡量治疗装备，与账号属性无关。",
 "One reference profile for everyone. Compare offensive gear as it is now in the same element and weapon context, independently of account stats.": "所有人使用同一参考档案。在相同元素与武器环境下，按该装备当前的情况衡量输出装备，与账号属性无关。",
 "The current equipped item is subtracted first. Its current stats are then rated using the remaining build, rather than added on top of its own current stats.": "先扣除当前已装备的装备。其当前属性再按剩余配装进行评分，而不是叠加在其自身当前属性之上。",
