 "Parts the game did not send at this login stay empty and are listed after the import. Open those windows in the game and capture again.": "本次登录时游戏未发送的部分将保持为空，并在导入后列出。请在游戏中打开这些窗口后重新抓取。",
 "Saving and public builds": "保存与公开配装",
