 "Choose DPS, Tank, Healer or Balance at the top right of the card and press \"Save build\". Each role keeps its own public card.": "在卡片右上角选择输出、坦克、治疗或均衡，然后按“保存配装”。每个定位各自保留其公开卡片。",
 "Only the unedited import": "仅限未编辑的导入",
