 "Verified Titan · own .tofbuild": "已验证泰坦 · 自有 .tofbuild",
 "All pieces: verified Titan · own .tofbuild": "所有装备：已验证泰坦 · 自有 .tofbuild",
 "Every piece behind this score is Titan from the player’s own .tofbuild, with known original stats.": "此评分所含的每件装备均为玩家自有 .tofbuild 中的泰坦装备，且原始属性已知。",
 "Titan item from the player’s own .tofbuild, with known original stats. Inspected and non-Titan gear is not verified.": "来自玩家自有 .tofbuild 的泰坦装备，原始属性已知。未检查的装备与非泰坦装备均未经验证。",
 "Counted stats converted into rating points; 100 = the most valuable single roll at full Titan across all stats.": "计入的属性换算为评分点数；100 = 所有属性中，泰坦完全强化时单次词条的最高价值。",
 "universal ATK, the element’s ATK, ATK % and DMG %, Crit and Crit Rate %; other stats give 0.": "通用攻击，该元素的攻击、攻击% 与伤害%，暴击与暴击率%；其他属性记为 0。",
 "the better flat ATK, ATK % and DMG % of either element of the pair; Crit counts, other stats give 0.": "该组合两种元素中较优的固定攻击、攻击% 与伤害%；计入暴击，其他属性记为 0。",
 "The perfect item of the slot: the best legal set of counted stats, every roll on the most valuable one, at full Titan (100 %).": "该栏位的完美装备：计入属性的最佳合法组合，每次词条都落在最具价值的属性上，泰坦完全强化（100%）。",
 "Current values of each item. Titan growth is random, so other players’ values before Titan cannot be recovered.": "各装备的当前数值。泰坦成长是随机的，因此无法还原其他玩家在泰坦前的数值。",
 "Reference player": "参考玩家",
 "These baseline values are site assumptions, not official game constants; crit uses the game’s crit formula at this enemy level.": "这些基准值是站点假设，并非官方游戏常数；暴击在该敌人等级下使用游戏的暴击公式计算。",
 "One reference profile for everyone: each stat is rated by the ATK it adds to the same reference player (crit and DMG % are not rated).": "所有人使用同一参考档案：每项属性按其为同一参考玩家增加的攻击进行评分（暴击与伤害% 不计分）。",
 "One reference profile for everyone: each stat is rated by the effective HP it adds against the selected element to the same reference tank.": "所有人使用同一参考档案：每项属性按其针对所选元素为同一参考坦克增加的有效生命进行评分。",
 "Counted stats converted into rating points; 100 = the most valuable single roll at full Titan among the stats this role rates.": "计入的属性换算为评分点数；100 = 该定位所评分属性中，泰坦完全强化时单次词条的最高价值。",
 "universal ATK, the element’s ATK and ATK %; crit, DMG % and other stats give 0.": "通用攻击，该元素的攻击与攻击%；暴击、伤害% 及其他属性记为 0。",
 "HP, HP %, general RES (counts like the element’s own), the element’s RES and RES %; other stats give 0.": "生命、生命%、通用抗性（与该元素自身抗性同样计入）、该元素抗性与抗性%；其他属性记为 0。",
 "These baseline values are site assumptions, not official game constants; damage reduction uses the game’s defence formula at this level.": "这些基准值是站点假设，并非官方游戏常数；减伤在该等级下使用游戏的防御公式计算。",
 "All elements · best element of each server": "所有元素 · 每个服务器的最佳元素",
 "Added by Titan: this stat did not exist before Titan": "泰坦追加：此属性在泰坦之前并不存在",
