 "An SSR can drop early, but the fixed cycle still awards an SSR on pull 80.": "SSR 可能提前掉落，但固定周期仍会在第 80 抽时给予一个 SSR。",
 "An SSR matrix can drop early, but the fixed cycle still awards an SSR on pull 40.": "SSR 意志可能提前掉落，但固定周期仍会在第 40 抽时给予一个 SSR。",
 "About the average rate:": "关于平均概率：",
 "2.00% for weapons and 4.20% for matrices are average SSR rates after accounting for the hard guarantee. They are not the chance on every individual pull.": "计入硬保底后，武器的平均 SSR 概率为 2.00%，意志为 4.20%。这些并非每次单抽的几率。",
 "How pity works": "保底机制",
 "SSR and SR protection.": "SSR 与 SR 保底。",
 "An SSR is guaranteed on weapon pull 80 or matrix pull 40. Also, if no SR or SSR appears for {{srPity}} pulls, the next pull guarantees SR or higher.": "武器第 80 抽或意志第 40 抽必定获得 SSR。此外，若连续 {{srPity}} 抽都未出现 SR 或 SSR，则下一抽必定获得 SR 或更高稀有度。",
 "Pity carries over.": "保底会延续。",
 "Limited weapon pity carries between weapon event banners; matrix pity carries between matrix event banners. The two tracks are independent.": "限定武器保底会在武器活动卡池之间延续；意志保底会在意志活动卡池之间延续。两条轨道相互独立。",
 "Separate guarantees.": "保底各自独立。",
 "The rarity guarantee (SSR) and the featured-item result (50/50) are separate events. A win or loss does not change rarity pity.": "稀有度保底（SSR）与特选物品结果（50/50）是两件独立的事。胜利或歪都不会改变稀有度保底。",
 "Early SSR.": "提前出 SSR。",
 "An early drop does not reset the fixed guarantee cycle. For example, an SSR on pull 23 does not cancel the next guaranteed SSR on pull 80.": "提前掉落不会重置固定保底周期。例如，第 23 抽出的 SSR 不会取消第 80 抽的下一个保底 SSR。",
 "Featured item: 50/50": "特选物品：50/50",
 "Standard SSR": "常驻 SSR",
 "next SSR is standard": "下一个 SSR 为常驻",
 "next SSR is featured": "下一个 SSR 为特选",
