 "Start before you log in": "登录前启动",
 "Press Start, then log into your character in Hykros. If you are elsewhere, teleport to Hykros and log into your character again.": "按下“开始”，然后在 Hykros 中登录你的角色。如果你在其他地方，请传送到 Hykros 后重新登录你的角色。",
