 "Totals.": "合计。",
 "Average at 5 rolls = base + 5 × (min + max) / 2; maximum = base + 5 × max. The Gold rows are checked against the reference Stat ranges table on every run.": "5 次词条的平均值 = 基础值 + 5 ×（最小值 + 最大值）/ 2；最大值 = 基础值 + 5 × 最大值。金色行每次运行都会与参考的属性范围表进行核对。",
 "Chances by slot.": "按栏位划分的几率。",
 "Each item names its pool (EquipmentDataTable → RandomModifyData). One draw uses positive weights; -1 marks a guaranteed stat.": "每件物品标明其词条池（EquipmentDataTable → RandomModifyData）。单次抽取使用正权重；-1 表示必定属性。",
 "Whole-item model.": "整件物品模型。",
 "Rare properties.": "稀有属性。",
 "EquipUncommonModifyData: each entry becomes available once the augmentation count reaches TupoCountLimited; chance = Weight / sum of available weights.": "EquipUncommonModifyData：每个条目在增益次数达到 TupoCountLimited 后可用；几率 = 权重 / 可用权重之和。",
 "Roll chance.": "词条几率。",
 "EquipUncommonRateData.UncommonRate per augmentation-count row; counts between rows are not confirmed.": "EquipUncommonRateData.UncommonRate 按每个增益次数行给出；行与行之间的次数尚未确认。",
 "Main-stat growth.": "主属性成长。",
 "EquipRandomModifyData.TupoAddABSValueMap: five weighted bands per count; expected value assumes a uniform value inside a band.": "EquipRandomModifyData.TupoAddABSValueMap：每个次数有五个加权区间；期望值假定区间内数值均匀分布。",
 "Added stats.": "追加属性。",
 "The ideal rule derived from captured items and used on the Tools pages (build-reference titanGrowth).": "从抓取的物品推导出并用于工具页面的理想规则（build-reference titanGrowth）。",
 "Weights.": "权重。",
