 "Other systems.": "其他系统。",
 "Cost.": "消耗。",
 "EquipStrengthenDataTable row N is the price of reaching +N (NeedItems, NeedGolds); a range is the sum of its rows.": "EquipStrengthenDataTable 第 N 行为强化到 +N 的价格（NeedItems、NeedGolds）；范围为其各行之和。",
 "Main stats.": "主属性。",
