 "If the buff is granted on a skill press / some action, it is ": "如果增益是在按下技能或执行某个动作时获得的，则它属于",
 "ACTIVE": "主动",
 " (compare among actives).": "（与其他主动增益比较）。",
 "If the buff is granted simply for the weapon existing in your build, it is ": "如果增益只是因为你的配装中存在该武器而获得，则它属于",
 "PASSIVE": "被动",
 "Relics: Final and Elemental are counted separately, and relics do ": "源器：Final 与元素伤害分别计算，且源器确实可以与特质或意志",
 " combine with traits or matrices.": "叠加。",
 "Those specific relics are ": "这些特定源器受上述分组规则约束。出现在",
 "In the end, all resulting combat damage in your build scales as the product of two fundamental multiplier blocks: ": "最终，你配装中的所有战斗伤害都按两个基础倍率块的乘积缩放：",
 "Final Dmg × Elemental Dmg": "Final Dmg × 元素伤害",
 "In turn, each of these two blocks is multiplied across its own independent categories: ": "这两个块中的每一个又会在各自独立的类别之间相乘：",
 " from matrices multiplies by ": "来自意志的倍率与",
 " from active weapon buffs, by ": "武器主动增益的倍率相乘，再与",
 " from passive weapon buffs, traits, and relics. In the exact same way, ": "武器被动增益、特质与源器的倍率相乘。以完全相同的方式，",
 " multiplies across matrices, weapon active, weapon passive, traits, and relics.": "会在意志、武器主动、武器被动、特质与源器之间相乘。",
 "Total Multiplier = Final Dmg × Elemental Dmg": "总倍率 = Final Dmg × 元素伤害",
 "• Final Dmg: Matrix × Weapon Active × Weapon Passive × Traits × Relics": "• Final Dmg：意志 × 武器主动 × 武器被动 × 特质 × 源器",
 "• Elemental Dmg: Matrix × Weapon Active × Weapon Passive × Traits × Relics": "• 元素伤害：意志 × 武器主动 × 武器被动 × 特质 × 源器",
 "Frost Dmg and Elemental Dmg are one and the same thing": "冰霜伤害与元素伤害是同一回事。",
 "If one buff says ": "如果一个增益写着 ",
 "\"Frost Dmg +X%\"": "“冰霜伤害 +X%”",
 " and another says ": " 而另一个写着 ",
 "\"Elemental Dmg +Y%\"": "“元素伤害 +Y%”",
 "Drone": "Drone",
 "Instead of placing Lan's simulacrum trait into character traits, the developers placed it directly into the Matrix module (": "开发者没有把 Lan 的拟态特质放入角色特质中，而是将其直接放进了意志模块（",
 ", there was already an established sub-table ": "），当时已有一个既定子表 ",
 "ThunderAtkExtraUpMult": "ThunderAtkExtraUpMult",
 " (31 files). However, developers arbitrarily added a 'Be' prefix — ": "（31 个文件）。然而，开发者随意添加了 “Be” 前缀 — ",
 " (2 files) — and shoved new buffs there without any apparent logical rationale, creating an unintentional separate multiplier:": "（2 个文件）——并把新增增益塞进去，没有任何明显的逻辑依据，无意中形成了一个独立的倍率：",
