 "Disclaimer: Game Truth vs. Developer Inconsistencies": "免责声明：游戏真实情况与开发者的不一致",
 "The Multype tables 100% accurately reflect the real running game engine and active memory structures. However, in-game skill descriptions and translations do not always reflect the truth. Game developers occasionally introduce human errors, typos, or odd architectural quirks, causing an intuitively assumed category to land in a completely unexpected bucket under the hood.": "Multype 表格 100% 准确反映真实运行中的游戏引擎与活动内存结构。然而，游戏内技能描述与翻译并不总能反映事实。游戏开发者偶尔会引入人为错误、拼写错误或奇特的架构问题，导致某个直觉上认为的类别，在底层却落入了完全意想不到的分组中。",
 "Example 1: Lan Trait placed inside the Matrix category": "示例 1：Lan 特质被放入意志类别中",
