 "Example 2: Arbitrary 'Be' prefix in WeaponPassive (ThunderAtkBeExtraUpMult)": "示例 2：武器被动（ThunderAtkBeExtraUpMult）中任意的 'Be' 前缀",
 "2 FILES": "2 个文件",
 "31 FILES": "31 个文件",
 "These are merely the most striking examples of game descriptions diverging from actual engine code. Multype reveals the raw reality of the engine — letting you build around how buffs genuinely calculate in combat rather than how tooltips describe them.": "这些仅是游戏描述与实际引擎代码出现偏差的最典型示例。Multype 揭示了引擎的原始真相——让你依据增益在战斗中的实际计算方式来构建配装，而非依据提示框的描述。",
